document.addEventListener("DOMContentLoaded", function() {
  const newTabElement = document.getElementById("tabRestrictionData");
  if(newTabElement){
      const channel = new BroadcastChannel(atob(newTabElement.getAttribute("broadcastChannelName")));
      const errorPagePath = atob(newTabElement.getAttribute("errorPageContentPath"))
      const isCurrentAllowedPath = atob(newTabElement.getAttribute("pagePathAllowedInNewTab"))=="true"?true:false;
      const broadcastMessage = atob(newTabElement.getAttribute("broadcastMessage"));
      if(window.location.href.indexOf(errorPagePath)==-1){
        if(!isCurrentAllowedPath){
            channel.postMessage(broadcastMessage);
        }
        channel.addEventListener('message', (msg) => {
            if (msg.data === broadcastMessage && window.location.href.indexOf(errorPagePath)==-1 && !isCurrentAllowedPath) {
                window.location.href = errorPagePath;
            }
        });
      }
  }
});